return [
  { json: { ticket: 'Production server is down, customers cannot log in, revenue impacted' } },
  { json: { ticket: 'I was charged twice for my subscription this month' } },
  { json: { ticket: 'Do you offer volume discounts for 500 seats?' } },
  { json: { ticket: 'hmm' } }
];

// The System 2 reality: a general model returns free text, so we parse it.
// Tolerate markdown fences and surrounding prose. Any failure is flagged,
// and the Route Decision node sends flagged tickets to human_review.
return $input.all().map((item, i) => {
  const raw = String(item.json.response ?? '').trim();
  const ticket = $('Sample Tickets').all()[i].json.ticket;
  const latency_ms = Math.round((item.json.total_duration || 0) / 1e6);
  const output_tokens = item.json.eval_count ?? null;
  let parsed = null;
  let parse_error = null;
  try {
    const cleaned = raw.replace(/```(json)?/gi, '');
    const start = cleaned.indexOf('{');
    const end = cleaned.lastIndexOf('}');
    if (start === -1 || end === -1 || end <= start) throw new Error('no JSON object in response');
    parsed = JSON.parse(cleaned.slice(start, end + 1));
  } catch (e) {
    parse_error = 'parse_failed: ' + e.message;
  }
  let urgent = null, team = null, confidence = null;
  if (parsed) {
    urgent = typeof parsed.urgent === 'number' ? parsed.urgent : null;
    team = ['infra', 'billing', 'sales'].includes(parsed.team) ? parsed.team : null;
    confidence = typeof parsed.confidence === 'number' ? parsed.confidence : null;
    if (urgent === null || team === null) parse_error = 'invalid_fields: ' + raw.slice(0, 120);
  }
  return { json: { ticket, urgent, team, confidence, parse_error, output_tokens, latency_ms, raw_response: raw.slice(0, 500) } };
});

// Same routing rule as System 1: AI perceives, deterministic code decides.
// Extra branch: parse failures go to human_review (the System 2 failure mode System 1 doesn't have).
const CONF_MIN = 0.6;
return $input.all().map((item) => {
  const { ticket, urgent, team, confidence, parse_error, output_tokens, latency_ms } = item.json;
  let route;
  if (parse_error) route = 'human_review';
  else if (confidence < CONF_MIN) route = 'human_review';
  else if (urgent >= 0.7) route = 'page_oncall:' + team;
  else route = 'queue:' + team;
  return { json: { ticket, urgent, team, confidence, route, output_tokens, latency_ms } };
});
